CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS license_codes (id uuid PRIMARY KEY, code_hash text UNIQUE NOT NULL, plan text NOT NULL CHECK (plan IN ('trial','subscription','perpetual')), duration_days integer NOT NULL CHECK (duration_days >= 0), max_devices integer NOT NULL CHECK (max_devices > 0), status text NOT NULL DEFAULT 'available' CHECK (status IN ('available','redeemed','disabled')), created_at timestamptz NOT NULL DEFAULT now(), redeemed_at timestamptz);
CREATE TABLE IF NOT EXISTS licenses (id uuid PRIMARY KEY, license_no text UNIQUE NOT NULL, customer_id uuid, plan text NOT NULL, status text NOT NULL CHECK (status IN ('active','expired','revoked')), issued_at timestamptz NOT NULL, expires_at timestamptz, offline_until timestamptz NOT NULL, max_version text NOT NULL, features_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS license_devices (id uuid PRIMARY KEY, license_id uuid NOT NULL REFERENCES licenses(id) ON DELETE CASCADE, device_public_key text NOT NULL, device_fingerprint text NOT NULL, platform text NOT NULL, first_activated_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, status text NOT NULL CHECK (status IN ('active','deactivated','blocked')), UNIQUE (license_id, device_public_key));
CREATE TABLE IF NOT EXISTS activation_logs (id uuid PRIMARY KEY, license_id uuid REFERENCES licenses(id) ON DELETE SET NULL, device_id uuid REFERENCES license_devices(id) ON DELETE SET NULL, action text NOT NULL, result text NOT NULL, ip_hash text NOT NULL, client_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_versions (id uuid PRIMARY KEY, channel text NOT NULL, platform text NOT NULL, version text NOT NULL, minimum_license_version text NOT NULL, download_url text NOT NULL, sha256 text NOT NULL, signature text NOT NULL, released_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'draft');
CREATE INDEX IF NOT EXISTS idx_license_devices_license ON license_devices(license_id,status);
